# Load task progression info
import re, os

def load_grids():
    d = os.path.normpath(os.environ['RLM_SESSION_DIR'])
    path = d + '/../../sessions/' + os.path.basename(d) + '.jsonl'
    try:
        t = open(path).read()
    except:
        return {}

    G = {}
    # Find all labels and their positions
    sections = list(re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n', t))
    for i, m in enumerate(sections):
        label, h, w = m[1], int(m[2]), int(m[3])
        pos = m.end()

        # Collect h*w cells for this grid
        cell_end = t.find('\n', pos)
        if cell_end == -1:
            cell_end = len(t)
        cells = t[pos:cell_end].split()

        if len(cells) >= h * w:
            grid = [[int(cells[i*w + j]) for j in range(w)] for i in range(h)]
            G[label] = grid

    return G

G = load_grids()
print(f"Loaded {len(G)} grids:")
for k in G:
    print(f"  {k}: {len(G[k])}x{len(G[k][0]) if G[k] else 0}")
    print(G[k])

